  let timerId: ReturnType<typeof setTimeout> | null = null;
  let cancelled = false;

  function tick(): void {
    timerId = setTimeout(() => {
      if (cancelled) return;
      callback(...args);
      tick();
    }, delay);
  }

  tick();

